import java.util.Arrays;
import java.util.List;

class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
            int n = cost.size();
                    int m = cost.get(0).size();
                            
                                    // minCostGroup2[j] stores the minimum cost to connect node j of group 2 to any node in group 1
                                            int[] minCostGroup2 = new int[m];
                                                    Arrays.fill(minCostGroup2, Integer.MAX_VALUE);
                                                            for (int j = 0; j < m; j++) {
                                                                        for (int i = 0; i < n; i++) {
                                                                                        minCostGroup2[j] = Math.min(minCostGroup2[j], cost.get(i).get(j));
                                                                                                    }
                                                                                                            }
                                                                                                                    
                                                                                                                            // dp[mask] represents the minimum cost where mask encodes the visited nodes of group 2
                                                                                                                                    int numMasks = 1 << m;
                                                                                                                                            int[] dp = new int[numMasks];
                                                                                                                                                    Arrays.fill(dp, Integer.MAX_VALUE / 2);
                                                                                                                                                            dp[0] = 0;
                                                                                                                                                                    
                                                                                                                                                                            // Iterate through each node in group 1
                                                                                                                                                                                    for (int i = 0; i < n; i++) {
                                                                                                                                                                                                int[] nextDp = new int[numMasks];
                                                                                                                                                                                                            Arrays.fill(nextDp, Integer.MAX_VALUE / 2);
                                                                                                                                                                                                                        
                                                                                                                                                                                                                                    // Try connecting node i to every node j in group 2
                                                                                                                                                                                                                                                for (int j = 0; j < m; j++) {
                                                                                                                                                                                                                                                                int c = cost.get(i).get(j);
                                                                                                                                                                                                                                                                                int bit = 1 << j;
                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                for (int mask = 0; mask < numMasks; mask++) {
                                                                                                                                                                                                                                                                                                                                    // Transition 1: connect to node j as the first connection for group 1 node i
                                                                                                                                                                                                                                                                                                                                                        nextDp[mask | bit] = Math.min(nextDp[mask | bit], dp[mask] + c);
                                                                                                                                                                                                                                                                                                                                                                            // Transition 2: connect node i to additional nodes in group 2
                                                                                                                                                                                                                                                                                                                                                                                                nextDp[mask | bit] = Math.min(nextDp[mask | bit], nextDp[mask] + c);
                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                        dp = nextDp;
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                // For any nodes in group 2 not yet covered by the end, connect them using their minimum cost edge
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int ans = Integer.MAX_VALUE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int mask = 0; mask < numMasks; mask++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int totalCost = dp[mask];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int j = 0; j < m; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ((mask & (1 << j)) == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            totalCost += minCostGroup2[j];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ans = Math.min(ans, totalCost);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return ans;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }